#include <Arduino.h>

const uint8_t R = 2, G = 3, B = 4;
unsigned long phaseStart;
uint8_t phase = 0;

void showPhase(uint8_t p) {
  digitalWrite(R, p < 3 ? HIGH : LOW);
  digitalWrite(G, (p == 1 || p == 2) ? HIGH : LOW);
  digitalWrite(B, p == 2 ? HIGH : LOW);
}

void setup() {
  digitalWrite(R, LOW);
  digitalWrite(G, LOW);
  digitalWrite(B, LOW);
  pinMode(R, OUTPUT);
  pinMode(G, OUTPUT);
  pinMode(B, OUTPUT);
  phaseStart = millis();
  showPhase(phase);
}

void loop() {
  unsigned long now = millis();
  while ((unsigned long)(now - phaseStart) >= 3000UL) {
    phaseStart += 3000UL;
    phase = (phase + 1) % 4;
    showPhase(phase);
  }
}
